//! The explorer's icons, generated by `tools/make_icons.py` into
//! `assets/icons/ui/`: 16×16, 1.2 px strokes, one color, tinted with the
//! theme at draw time.
//!
//! Kinds of files get a symbol (braces for JSON, a padlock for lockfiles…);
//! programming languages get a tile with two letters. To add a language,
//! add it to `TILES` in the script, run it, and map its extension below.

use iced::widget::svg::Handle;
use std::collections::HashMap;
use std::sync::LazyLock;

macro_rules! icons {
    ($($name:literal),* $(,)?) => {
        [$(($name, Handle::from_memory(
            include_bytes!(concat!("../../../assets/icons/ui/", $name, ".svg")).as_slice(),
        ))),*]
    };
}

static ICONS: LazyLock<HashMap<&'static str, Handle>> = LazyLock::new(|| {
    HashMap::from(icons![
        "chevron-right",
        "chevron-down",
        "folder",
        "folder-open",
        "file",
        "text",
        "markdown",
        "braces",
        "markup",
        "config",
        "lock",
        "git",
        "image",
        "package",
        "book",
        "license",
        "terminal",
        "database",
        "lang/rs",
        "lang/py",
        "lang/js",
        "lang/ts",
        "lang/go",
        "lang/c",
        "lang/h",
        "lang/cpp",
        "lang/java",
        "lang/kt",
        "lang/swift",
        "lang/rb",
        "lang/php",
        "lang/cs",
        "lang/fs",
        "lang/lua",
        "lang/dart",
        "lang/zig",
        "lang/ex",
        "lang/erl",
        "lang/hs",
        "lang/ml",
        "lang/scala",
        "lang/r",
        "lang/jl",
        "lang/nim",
        "lang/elm",
        "lang/vue",
        "lang/svelte",
        "lang/css",
        "lang/scss",
        "lang/less",
        "lang/vim",
        "lang/pl",
        "lang/clj",
        "lang/gd",
        "lang/font",
    ])
});

/// The icon called `name` (a file stem in `assets/icons/ui/`).
pub fn get(name: &str) -> &'static Handle {
    ICONS.get(name).unwrap_or_else(|| &ICONS["file"])
}

pub fn for_file(file_name: &str) -> &'static Handle {
    get(name_for(file_name))
}

/// Which icon a file gets, by its name first and then its extension.
pub fn name_for(file_name: &str) -> &'static str {
    let lower = file_name.to_ascii_lowercase();
    let ext = lower.rsplit_once('.').map_or("", |(_, e)| e);

    match lower.as_str() {
        "cargo.toml" | "package.json" | "pyproject.toml" | "go.mod" | "gemfile"
        | "composer.json" | "build.gradle" | "build.gradle.kts" | "pom.xml" | "deno.json"
        | "mix.exs" => {
            return "package";
        }
        "package-lock.json" | "pnpm-lock.yaml" | "go.sum" => return "lock",
        "dockerfile" | "containerfile" | "makefile" | "justfile" | "cmakelists.txt" => {
            return "config";
        }
        _ => {}
    }
    if lower.starts_with(".git") {
        return "git";
    }
    if lower.starts_with("readme") {
        return "book";
    }
    if ["license", "licence", "copying", "notice"].iter().any(|p| lower.starts_with(p)) {
        return "license";
    }

    match ext {
        "rs" => "lang/rs",
        "py" | "pyi" => "lang/py",
        "js" | "mjs" | "cjs" | "jsx" => "lang/js",
        "ts" | "mts" | "cts" | "tsx" => "lang/ts",
        "go" => "lang/go",
        "c" => "lang/c",
        "h" => "lang/h",
        "cpp" | "cc" | "cxx" | "c++" | "hpp" | "hh" | "hxx" => "lang/cpp",
        "java" => "lang/java",
        "kt" | "kts" => "lang/kt",
        "swift" => "lang/swift",
        "rb" => "lang/rb",
        "php" => "lang/php",
        "cs" => "lang/cs",
        "fs" | "fsx" | "fsi" => "lang/fs",
        "lua" => "lang/lua",
        "dart" => "lang/dart",
        "zig" => "lang/zig",
        "ex" | "exs" => "lang/ex",
        "erl" | "hrl" => "lang/erl",
        "hs" => "lang/hs",
        "ml" | "mli" => "lang/ml",
        "scala" | "sc" => "lang/scala",
        "r" => "lang/r",
        "jl" => "lang/jl",
        "nim" => "lang/nim",
        "elm" => "lang/elm",
        "vue" => "lang/vue",
        "svelte" => "lang/svelte",
        "css" => "lang/css",
        "scss" | "sass" => "lang/scss",
        "less" => "lang/less",
        "vim" => "lang/vim",
        "pl" | "pm" => "lang/pl",
        "clj" | "cljs" | "cljc" | "edn" => "lang/clj",
        "gd" => "lang/gd",
        "ttf" | "otf" | "woff" | "woff2" => "lang/font",
        "md" | "markdown" | "mdx" => "markdown",
        "txt" | "log" | "rst" | "adoc" | "org" | "tex" => "text",
        "json" | "jsonc" | "json5" => "braces",
        "toml" | "yaml" | "yml" | "ini" | "cfg" | "conf" | "properties" | "env" | "plist" => {
            "config"
        }
        "html" | "htm" | "xhtml" | "xml" => "markup",
        "png" | "jpg" | "jpeg" | "gif" | "webp" | "ico" | "bmp" | "avif" | "tiff" | "svg" => {
            "image"
        }
        "sh" | "bash" | "zsh" | "fish" | "ps1" | "bat" | "cmd" | "nu" => "terminal",
        "sql" | "db" | "sqlite" => "database",
        "lock" => "lock",
        "zip" | "tar" | "gz" | "tgz" | "xz" | "bz2" | "7z" | "rar" | "zst" => "package",
        // Remaining dotfiles (.editorconfig, .env.local, .prettierrc) are configuration.
        _ if lower.starts_with('.') => "config",
        _ => "file",
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn names() {
        let cases = [
            ("main.rs", "lang/rs"),
            ("App.TSX", "lang/ts"),
            ("README.md", "book"),
            ("notes.md", "markdown"),
            ("Cargo.toml", "package"),
            ("Cargo.lock", "lock"),
            ("rustfmt.toml", "config"),
            (".gitignore", "git"),
            (".editorconfig", "config"),
            ("LICENSE-MIT", "license"),
            ("logo.svg", "image"),
            ("install.sh", "terminal"),
            ("deny.toml", "config"),
            ("data.bin", "file"),
        ];
        for (file, icon) in cases {
            assert_eq!(name_for(file), icon, "{file}");
        }
    }

    #[test]
    fn every_mapped_icon_exists() {
        let samples = [
            "a.rs",
            "a.py",
            "a.js",
            "a.ts",
            "a.go",
            "a.c",
            "a.h",
            "a.cpp",
            "a.java",
            "a.kt",
            "a.swift",
            "a.rb",
            "a.php",
            "a.cs",
            "a.fs",
            "a.lua",
            "a.dart",
            "a.zig",
            "a.ex",
            "a.erl",
            "a.hs",
            "a.ml",
            "a.scala",
            "a.r",
            "a.jl",
            "a.nim",
            "a.elm",
            "a.vue",
            "a.svelte",
            "a.css",
            "a.scss",
            "a.less",
            "a.vim",
            "a.pl",
            "a.clj",
            "a.gd",
            "a.ttf",
            "a.md",
            "a.txt",
            "a.json",
            "a.toml",
            "a.html",
            "a.png",
            "a.sh",
            "a.sql",
            "a.lock",
            "a.zip",
            ".env",
            "x",
            "README",
            "LICENSE",
            ".gitignore",
            "Cargo.toml",
        ];
        for file in samples {
            assert!(ICONS.contains_key(name_for(file)), "{file} -> {}", name_for(file));
        }
        for name in ["chevron-right", "chevron-down", "folder", "folder-open"] {
            assert!(ICONS.contains_key(name), "{name}");
        }
    }
}
